      'ရေကြည်တိမ် (Glaucoma) သည် မျက်စိတွင်းဖိအား (IOP) မြင့်တက်လာခြင်းကြောင့် အမြင်အာရုံကြော (Optic Nerve) တဖြည်းဖြည်း ပျက်စီးကာ အသံတိတ် မျက်စိကွယ်စေသော ရောဂါဖြစ်ပြီး ပျက်စီးသွားသော အမြင်အာရုံကို ပြန်မရနိုင်ပါ။',
