    content: [
      'အသက် ၅၀ ကျော်လာသူများတွင် မျက်စိတိမ်ပြီးလျှင် အမြင်အာရုံ ချို့ယွင်းမှုဖြစ်စေသော ဒုတိယအဓိက အကြောင်းရင်းမှာ အသက်ကြီးမြင်လွှာဗဟိုယိုယွင်းခြင်း (Age-Related Macular Degeneration - AMD) ဖြစ်ပါသည်။ မြင်လွှာ၏ အလယ်ဗဟိုရှိ အသေးစိတ်ပုံရိပ်ဖော်ပေးသော မက်ကူလာ (Macula) အဝါရောင်အစက် နေရာတွင် အညစ်အကြေးများ (Drusen) စုပုံလာရာမှ စတင်ပါသည်။',
      'Dry AMD နှင့် Wet AMD ကွာခြားချက် - \n၁။ အခြောက်ပုံစံ (Dry AMD - ၈၅-၉၀%): ဆဲလ်များ တဖြည်းဖြည်း သေဆုံးကာ အမြင်အာရုံ ဗဟိုဝေဝါးလာခြင်း ဖြစ်ပါသည်။ နှစ်ပေါင်းများစွာကြာမှ တဖြည်းဖြည်း ဆိုးလာတတ်ပါသည်။\n၂။ အစိုပုံစံ (Wet AMD - ၁၀-၁၅%): မက်ကူလာအောက်တွင် မူမမှန်သော သွေးကြောသစ်များ ပေါက်ကာ သွေးနှင့် အရည်များ ယိုစိမ့်ထွက်လာခြင်း ဖြစ်ပါသည်။ ရက်ပိုင်း သို့မဟုတ် သီတင်းပတ်ပိုင်းအတွင်း ဗဟိုအမြင်အာရုံ လုံးဝအမည်းကွက် ဖြစ်သွားနိုင်သဖြင့် အရေးပေါ် မျက်လုံးတွင်း Anti-VEGF ထိုးဆေးဖြင့် ကုသရပါမည်။',
      'Amsler Grid စစ်ဆေးနည်း - \nအကွက်ချထားသော စာရွက်ပေါ်ရှိ ဗဟိုအနက်စက်ကို မျက်မှန်တပ်ထားသူဖြစ်ပါက မျက်မှန်တပ်လျက် ၁၄ လက်မအကွာမှ မျက်စိတစ်ဖက်စီ ပိတ်၍ ကြည့်ပါ။ အကယ်၍ လိုင်းဖြောင့်များသည် ကောက်ကွေးလှိုင်းတွန့်နေပါက သို့မဟုတ် အကွက်အချို့ ပျောက်ကွယ်မည်းနက်နေပါက ချက်ချင်း မျက်စိအထူးကုနှင့် ပြသရပါမည်။',
      'မျက်စိအားကောင်းစေသော အစားအစာများနှင့် နေထိုင်မှုပုံစံ - \n• အစိမ်းရင့်ရောင် ဟင်းသီးဟင်းရွက်များ (ကိုက်လန်၊ ဟင်းနုနွယ်၊ မုန်ညင်း) နှင့် ကြက်ဥအနှစ်တွင် Lutein နှင့် Zeaxanthin ဓာတ်များ ကြွယ်ဝစွာ ပါဝင်သဖြင့် မျက်စိမြင်လွှာကို နေရောင်ခြည်ဒဏ်မှ အကာအကွယ်ပေးပါသည်။\n• ငါးသလောက်၊ ဆယ်လ်မွန်၊ တူနာ စသည့် ပင်လယ်ငါးများတွင်ပါသော Omega-3 Fatty Acids ကို ပုံမှန် စားသုံးပါ။\n• ဆေးလိပ်သောက်ခြင်းသည် AMD ဖြစ်နိုင်ခြေကို ၄ ဆအထိ မြင့်တက်စေသဖြင့် ဆေးလိပ်ကို မဖြစ်မနေ ဖြတ်ရပါမည်။'
    ]
