    summary: 'ရေကျပြီးနောက် အိမ်တွင်း မှိုစွဲခြင်း (Mold) ရှင်းလင်းနည်း၊ စိတ်ဒဏ်ရာ (PTSD) နှင့် စိုးရိမ်ပူပန်မှု လျှော့ချနည်း၊ ဆီးချို၊ သွေးတိုးနှင့် ကျောက်ကပ် နာတာရှည် လူနာများ ပြန်လည်ထူထောင်ရေး လမ်းညွှန်။',
